    /** The words by language: code to (English text to translation). Rows that do not fit the columns are skipped. */
    fun build(): Map<String, Map<String, String>> {
        val tables = CODES.associateWith { HashMap<String, String>() }
        for (row in ROWS) {
            val parts = row.split(" | ")
            if (parts.size != CODES.size + 1) continue
            val english = parts[0].trim()
            for ((i, code) in CODES.withIndex()) {
                val text = parts[i + 1].trim()
                if (text.isNotEmpty()) tables.getValue(code)[english] = text
            }
        }
        return tables
    }
}
